    && page.properties?.Status?.status?.name === "Brief"
    && page.properties?.["AI draft"]?.select === null;
}

function readBrief(page) {
  const p = page.properties;
  const richText = field => (p[field]?.rich_text ?? []).map(part => part.plain_text).join("").trim();
  return {
    Restaurant: richText("Restaurant"),
    "Dish or offer": richText("Dish or offer"),
    Platform: (p.Platform?.select?.name ?? "").trim(),
    "Tone notes": richText("Tone notes"),
  };
}

function ownerId(page) {
  const owners = page.properties.Owner.people;
  return owners.length === 1 ? owners[0].id : "";
}

const page = $json;
const outcome = $("Plan Draft Outcome").item.json;
if (page.id !== outcome.pageId || !isEligible(page)
    || JSON.stringify(readBrief(page)) !== JSON.stringify(outcome.brief)) {
  return {json: {apply: false}};
}
const properties = {"AI draft": {select: {name: outcome.draftStatus}}};
const numbered = values => ({rich_text: values.map((value, i) => ({
  type: "text",
  text: {content: `${i + 1}. ${value}${i === values.length - 1 ? "" : "\n"}`},
}))});
if (outcome.draftStatus === "ready") {
  properties.Captions = numbered(outcome.draft.captions);
  properties["Shot list"] = numbered(outcome.draft.shot_list);
}
return {json: {
  apply: true, pageId: page.id, ownerId: ownerId(page), draftStatus: outcome.draftStatus,
  reason: outcome.reason, body: {properties},
}};

function pageTitle(page) {
  return (page.properties.Name.title ?? []).map(part => part.plain_text).join("") || "Untitled piece";
}

function slackLink(url, title) {
  if (!/^https:\/\/[^\s<>|]+$/.test(url)) throw new Error("Expected a Notion page URL");
  const label = title.replaceAll("|", "/").replace(/[\r\n]/g, " ")
    .replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
  return `<${url}|${label}>`;
}

const page = $json;
const expected = $("Prepare Notion Update").item.json;
if (page.id !== expected.pageId || page.properties["AI draft"].select?.name !== expected.draftStatus) {
  throw new Error(`Could not verify AI draft on page ${expected.pageId}`);
}
if (expected.draftStatus === "ready") {
  for (const field of ["Captions", "Shot list"]) {
    const actual = page.properties[field].rich_text.map(part => part.plain_text).join("");
    const target = expected.body.properties[field].rich_text.map(part => part.text.content).join("");
    if (actual !== target) throw new Error(`Could not verify ${field} on page ${page.id}`);
  }
  return {json: {failed: false}};
}
return {json: {
  failed: true, ownerId: expected.ownerId,
  text: `AI draft failed for ${slackLink(page.url, pageTitle(page))}. ${expected.reason}.`,
}};

const routes = $("Desk Settings").first().json.slackOwnerIds;
const {ownerId, text} = $json;
const slackUser = routes[ownerId];
if (!ownerId || !/^[UW][A-Z0-9]+$/.test(slackUser ?? "")) {
  throw new Error(`No Slack user ID configured for Notion owner ${ownerId || "(missing owner)"}`);
}
if (text.length > 40000) throw new Error(`Slack message for owner ${ownerId} exceeds 40000 characters`);
return {json: {slackUser, text}};

if ($json.ok !== true || !$json.channel?.id) {
  throw new Error(`Slack conversations.open failed: ${$json.error ?? "missing channel"}`);
}
return {json: {body: {
  channel: $json.channel.id,
  text: $("Resolve Slack Owner").item.json.text,
  unfurl_links: false,
  unfurl_media: false,
}}};

if ($json.ok !== true || !$json.ts || !$json.channel) {
  throw new Error(`Slack chat.postMessage failed: ${$json.error ?? "missing message receipt"}`);
}
return {json: {channel: $json.channel, ts: $json.ts}};
